-- SPEC-237: fornecedor de cada peça a partir da planilha Produtos da Connect (14/10/2026, coluna nmFornecedor).
-- Casamento por nome (sem acento/pontuação/LTDA/ME...) com contatos tipo fornecedor; quando o nome bate com mais de um
-- cadastro (filiais), desempate: fornecedor da marca da peça → cadastro com pedido/NF → matriz (/0001) → único com CNPJ.
-- 4303 peças. Ficam sem: 38 (TARGETTI 36, MUNDIAL LUX 2 — sem cadastro), 1 (NORTEL, duas filiais sem matriz),
-- 201 sem fornecedor na planilha, 1 código da planilha que não existe no banco.
--  1. produto_fornecedores: um vínculo por peça (só onde não existe), observacao = marca desta carga.
--  2. produtos.fornecedor_principal_id: preenchido só onde está vazio (é o campo que a edição de peça mostra/grava).
--     Nenhum principal já preenchido diverge da planilha.
--  3. Gatilho: trocar o fornecedor principal na edição cria o vínculo em produto_fornecedores (se não existir).
BEGIN;

CREATE TEMP TABLE _forn_planilha (codigo_produto integer, fornecedor_id uuid, como text) ON COMMIT DROP;
