INSERT INTO public.produto_fornecedores (produto_id, fornecedor_id, ativo, observacao)
SELECT p.id, f.fornecedor_id, true, 'SPEC-237: planilha Produtos da Connect (14/10/2026), nmFornecedor'
  FROM _forn_planilha f JOIN public.produtos p ON p.codigo_produto = f.codigo_produto
ON CONFLICT (produto_id, fornecedor_id) DO NOTHING;

UPDATE public.produtos p
   SET fornecedor_principal_id = f.fornecedor_id
  FROM _forn_planilha f
 WHERE p.codigo_produto = f.codigo_produto AND p.fornecedor_principal_id IS NULL;

CREATE OR REPLACE FUNCTION public.trg_produto_fornecedor_principal_vinculo()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  IF NEW.fornecedor_principal_id IS NOT NULL
     AND NEW.fornecedor_principal_id IS DISTINCT FROM (CASE WHEN TG_OP = 'UPDATE' THEN OLD.fornecedor_principal_id END) THEN
    INSERT INTO public.produto_fornecedores (produto_id, fornecedor_id, ativo, observacao)
    VALUES (NEW.id, NEW.fornecedor_principal_id, true, 'Fornecedor principal escolhido no cadastro da peça')
    ON CONFLICT (produto_id, fornecedor_id) DO NOTHING;
  END IF;
  RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION public.trg_produto_fornecedor_principal_vinculo() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS trg_produto_fornecedor_principal_vinculo ON public.produtos;
CREATE TRIGGER trg_produto_fornecedor_principal_vinculo
  AFTER INSERT OR UPDATE OF fornecedor_principal_id ON public.produtos
  FOR EACH ROW EXECUTE FUNCTION public.trg_produto_fornecedor_principal_vinculo();

COMMIT;
